// PERF FIXTURE (rtl-buddy-cdc#253) — hierarchical/abstraction scaling.
//
// 50 instances of a single-clock pipeline subtree `pipe` (each 20
// clk_a flops, carrying NO crossing) plus a tiny 2-clock CDC fabric with
// exactly one real async crossing (clk_a -> clk_b). The FLAT netlist has
// every pipe flop present (the analyzer walks them all); the BLACKBOXED
// netlist summarises each single-clock pipe to its port boundary, so the
// analyzer walks only the fabric flops. Both variants report the SAME one
// async crossing — that parity, with far fewer flops walked, is the win.

module pipe (
    input  wire       clk,
    input  wire [3:0] d_in,
    output wire [3:0] d_out
);
    reg [3:0] s0;
    reg [3:0] s1;
    reg [3:0] s2;
    reg [3:0] s3;
    reg [3:0] s4;
    reg [3:0] s5;
    reg [3:0] s6;
    reg [3:0] s7;
    reg [3:0] s8;
    reg [3:0] s9;
    reg [3:0] s10;
    reg [3:0] s11;
    reg [3:0] s12;
    reg [3:0] s13;
    reg [3:0] s14;
    reg [3:0] s15;
    reg [3:0] s16;
    reg [3:0] s17;
    reg [3:0] s18;
    reg [3:0] s19;
    always_ff @(posedge clk) s0 <= d_in;
    always_ff @(posedge clk) s1 <= s0;
    always_ff @(posedge clk) s2 <= s1;
    always_ff @(posedge clk) s3 <= s2;
    always_ff @(posedge clk) s4 <= s3;
    always_ff @(posedge clk) s5 <= s4;
    always_ff @(posedge clk) s6 <= s5;
    always_ff @(posedge clk) s7 <= s6;
    always_ff @(posedge clk) s8 <= s7;
    always_ff @(posedge clk) s9 <= s8;
    always_ff @(posedge clk) s10 <= s9;
    always_ff @(posedge clk) s11 <= s10;
    always_ff @(posedge clk) s12 <= s11;
    always_ff @(posedge clk) s13 <= s12;
    always_ff @(posedge clk) s14 <= s13;
    always_ff @(posedge clk) s15 <= s14;
    always_ff @(posedge clk) s16 <= s15;
    always_ff @(posedge clk) s17 <= s16;
    always_ff @(posedge clk) s18 <= s17;
    always_ff @(posedge clk) s19 <= s18;
    assign d_out = s19;
endmodule

